def main():
    if not __debug__:
        raise SystemExit('optimized Python disables proof assertions')
    raw=base64.b85decode(PAYLOAD.encode('ascii'))
    if hashlib.sha256(raw).hexdigest()!=PAYLOAD_SHA256:
        raise SystemExit('payload SHA256 mismatch')
    with tempfile.TemporaryDirectory(prefix='r14_certificate_') as folder:
        root=Path(folder)
        with zipfile.ZipFile(io.BytesIO(raw)) as z:
            for info in z.infolist():
                path=PurePosixPath(info.filename)
                if path.is_absolute() or len(path.parts)!=1 or path.name in ('.','..'):
                    raise SystemExit('unsafe payload path')
                (root/path.name).write_bytes(z.read(info))
        env=os.environ.copy()
        env.update(OMP_NUM_THREADS='1',OPENBLAS_NUM_THREADS='1',MKL_NUM_THREADS='1')
        p=subprocess.run([sys.executable,'-B','verify_r14_package.py',*sys.argv[1:]],
                         cwd=root,env=env,check=False,preexec_fn=lambda:os.nice(19))
        raise SystemExit(p.returncode)

if __name__=='__main__':
    main()
